function avatar(category: ListCategory) {
  const fill = colors[category];
  return `data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="160" height="160" rx="80" fill="#${fill}"/><text x="50%" y="54%" text-anchor="middle" dominant-baseline="middle" font-family="Arial" font-size="76" font-weight="700" fill="white">R</text></svg>`)}`;
}

function maps(query: string) {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
}

function commons(file: string) {
  return `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}?width=1600`;
}

type StopInput = Partial<GuideStop> & {
  id: string;
  name: string;
  neighborhood: string;
  coordinates: [number, number];
  description: string;
  officialUrl: string;
  photo?: string;
  editorialUrls?: string[];
};

function stop(input: StopInput): GuideStop {
  const {
    id,
    name,
    neighborhood,
    coordinates,
    description,
    officialUrl,
    bookingUrl,
    photo: suppliedPhoto,
    editorialUrls = [],
    sourceUrls: extraSourceUrls = [],
    sourceEvidence,
    ...rest
  } = input;
  const photo = santiagoImageByStopId[id] ?? suppliedPhoto;
  if (!photo) throw new Error(`Missing sourced Santiago image for ${id}`);
  const mapUrl = sourceEvidence?.mapUrl ?? maps(`${name} Santiago Chile`);
  const sourceUrls = [officialUrl, bookingUrl, mapUrl, photo, ...editorialUrls, ...extraSourceUrls].filter(Boolean) as string[];
  return {
    id,
    poiId: input.poiId ?? `santiago-venue-${id.replace(/^santiago-/, "")}`,
    name,
    coordinates,
    description,
    subcategory: neighborhood,
    photo,
    imageSourceUrl: photo,
    imageSourceName: photo.includes("wikimedia") ? "Wikimedia Commons" : "Venue-specific sourced image",
    officialUrl,
    ...(bookingUrl ? { bookingUrl } : {}),
    sourceUrls: [...new Set(sourceUrls)],
    sourceEvidence: {
      officialUrl,
      mapUrl,
      currentStatusUrl: mapUrl,
      imageSourceUrl: photo,
      editorialUrls,
      checkedAt,
      notes: "The official venue, property, booking, museum, or tourism source and a current map listing were reviewed; no permanent-closure notice was found.",
      ...sourceEvidence,
    },
    ...rest,
  };
}

