function food(input: StopInput): GuideStop {
  return stop({
    category: "Food",
    venueKind: "food_drink",
    foodServiceType: "restaurant",
    cuisineTypes: ["Chilean"],
    attributeTags: ["local_favorite", "source-backed"],
    priceSource: input.officialUrl,
    ...input,
  });
}

function lodging(input: StopInput): GuideStop {
  return stop({
    category: "Stay",
    venueKind: "lodging",
    attributeTags: ["central", "bookable", "source-backed"],
    priceSource: input.bookingUrl ?? input.officialUrl,
    ...input,
  });
}

function nightlife(input: StopInput): GuideStop {
  return stop({
    category: "Nightlife",
    venueKind: "nightlife",
    attributeTags: ["evening", "source-backed"],
    priceSource: input.officialUrl,
    ...input,
  });
}

function place(input: StopInput): GuideStop {
  return stop({ attributeTags: ["source-backed", "daytime"], ...input });
}

