function source(name: string, url: string): ListSource { return { name, url }; }

function guideSources(primary: ListSource[], stops: GuideStop[]) {
  const all = [...primary, ...stops.map((item) => source(`${item.name} official source`, item.officialUrl ?? maps(`${item.name} Santiago Chile`)))];
  return [...new Map(all.map((item) => [item.url, item])).values()];
}

function guide(id: string, title: string, category: ListCategory, seoSlug: string, seoTitle: string, seoDescription: string, description: string, stops: GuideStop[], primary: ListSource[]): MapList {
  return {
    id,
    slug: id,
    seoSlug,
    seoTitle,
    seoDescription,
    title,
    description,
    photo: stops[0]?.photo,
    url: `/list/${id}`,
    category,
    location,
    creator: { id: "rguide-editorial", name: "R Guide Editorial", avatar: avatar(category) },
    upvotes: 0,
    createdAt,
    stops,
    sources: guideSources(primary, stops),
  };
}

